import argparse,hashlib,importlib.util,json,sys,urllib.request
from pathlib import Path
sys.path.insert(0,'scripts');import inspection
out=Path('artifacts/webtransport');original=inspection.metrics;snapshots=[]
keys=['war_sessions','war_incoming_messages_total','war_deliveries_total','war_datagrams_received','war_datagrams_submitted']
def sample(port):
 metrics=original(port)
 with urllib.request.urlopen(f'http://127.0.0.1:{port}/protocol-diagnostics',timeout=30) as response: rows=json.load(response)
 snapshots.append({'metrics':{k:metrics[k] for k in keys},'connections':rows})
 return metrics
inspection.metrics=sample
summary={'scope':'Diagnostic-only phase-gated per-connection protocol counters. Ready and measured snapshots taken while client waits, with small post-measurement ACK drain before capture. Exclude timings/RSS from ordinary comparisons. Quinn I/O counters are not kernel syscall counts. No ACK policy changes.','cases':[]}
def collect(path,result):
 result['protocol_diagnostic']=True;result['profile_diagnostic']=True;result['protocol_snapshots']=list(snapshots);path.write_text(json.dumps(result,indent=2)+'\n');assert result['passed'],path
 ready=next(e for e in result['events'] if e['event']=='ready');measured=next(e for e in result['events'] if e['event']=='measured')
 def find(event):
  target={k:event['metrics'][k] for k in keys};return next(s for s in reversed(snapshots) if s['metrics']==target)
 start={r['id']:r for r in find(ready)['connections']};end={r['id']:r for r in find(measured)['connections']};assert set(start)==set(end);assert len(start)==ready['metrics']['war_sessions']
 totals={k:sum(end[i][k]-start[i][k] for i in start) for k in next(iter(start.values())) if k!='id'};assert all(v>=0 for v in totals.values())
 details=measured['details'];verified=sum(details[k]['verified_unique'] for k in ['private','fanout']) if 'private' in details else details['healthy']['verified']+details['fanout']['verified']
 delta={k:measured['metrics'][k]-ready['metrics'][k] for k in keys if k!='war_sessions'}
 row={'receipt':str(path),'receipt_sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'sessions':len(start),'verified_application_deliveries':verified,'application_counters_delta':delta,'protocol_delta':totals,'per_verified_delivery':{k:v/verified for k,v in totals.items()},'tx_datagrams_per_quinn_io':totals['tx_datagrams']/max(1,totals['tx_ios'])};row['ready_ack_frequency_requests_sent']=sum(v['tx_ack_frequency'] for v in start.values());row['measured_ack_frequency_requests_sent']=sum(v['tx_ack_frequency'] for v in end.values());summary['cases'].append(row);(out/'ack-eight-protocol-gates-summary.json').write_text(json.dumps(summary,indent=2)+'\n');print('GATES',path,totals,flush=True)
for case in ['private','roomonly','mixed']:
 snapshots.clear();a=json.loads((out/f'owner-poll-{case}-owner-poll-1.json').read_text())['args'];a.update(server=str((out/'binaries/ack-eight-protocol-gates-relay').resolve()),seconds=8,output=str((out/f'ack-eight-protocol-gates-{case}.json').resolve()))
 for k in ['server','client','client_source_root','tls_front','tls_cert','tls_key','tls_ca','heap_profile','heap_library','output','fanout_latency_output']:
  if a.get(k) is not None:a[k]=Path(a[k])
 r=inspection.run(argparse.Namespace(**a));collect(a['output'],r)
spec=importlib.util.spec_from_file_location('load','scripts/datagram-load.py');load=importlib.util.module_from_spec(spec);spec.loader.exec_module(load)
for case,source in [('private','reliable-quantum-load-private-high-stream-1.json'),('mixed','owner-poll-mixed-high-datagram-1.json')]:
 snapshots.clear();a=json.loads((out/source).read_text())['args'];a.update(server=str(out/'binaries/ack-eight-protocol-gates-relay'),output=str(out/f'ack-eight-protocol-gates-paced-{case}.json'))
 for k in ['server','client','output']:a[k]=Path(a[k])
 r=load.run(argparse.Namespace(**a));collect(a['output'],r)
